 }

+void InhibitionControl::checkIdleActions()
+{
+    for (const QString &action : IDLE_ACTIONS) {
+        QDBusMessage msg = QDBusMessage::createMethodCall(SOLID_POWERMANAGEMENT_SERVICE,
+                                                          QStringLiteral("/org/kde/Solid/PowerManagement"),
+                                                          SOLID_POWERMANAGEMENT_SERVICE,
+                                                          QStringLiteral("isActionActive"));
+        msg << action;
+        QDBusPendingCall call = QDBusConnection::sessionBus().asyncCall(msg);
+        auto watcher = new QDBusPendingCallWatcher(call, this);
+        connect(watcher, &QDBusPendingCallWatcher::finished, this, [this, action](QDBusPendingCallWatcher *watcher) {
+            QDBusReply<bool> reply = *watcher;
+            // Assume the action is active if we can't tell, so the inhibition UI stays available
+            if (!reply.isValid() || reply.value()) {
+                m_activeIdleActions.insert(action);
+            } else {
+                m_activeIdleActions.remove(action);
+            }
+            updateHasIdleActions();
+            watcher->deleteLater();
+        });
+    }
+}
+
+void InhibitionControl::readScreenLockerConfig()
+{
+    KSharedConfig::Ptr config = KSharedConfig::openConfig(u"kscreenlockerrc"_s);
+    config->reparseConfiguration();
+    m_screenLockerAutolock = config->group(u"Daemon"_s).readEntry("Autolock", true);
+    updateHasIdleActions();
+}
+
+void InhibitionControl::updateHasIdleActions()
+{
+    m_hasIdleActions = m_screenLockerAutolock || !m_activeIdleActions.isEmpty();
+}
+
 void InhibitionControl::inhibit(const QString &reason)
 {
     InhibitMonitor::self().inhibit(reason, m_isSilent);
@@ -272,6 +355,11 @@ QBindable<bool> InhibitionControl::bindableIsManuallyInhibitedError()
